const $=id=>document.getElementById(id),iso=d=>new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10),addDays=(s,n)=>{let d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return iso(d)},today=iso(new Date()),monday=s=>{let d=new Date(s+'T12:00:00');return addDays(s,-((d.getDay()+6)%7))},fmt=h=>`${String(Math.floor(h)).padStart(2,'0')}:${String(Math.round(h%1*60)).padStart(2,'0')}`,num=s=>Number(s.split(':')[0])+Number(s.split(':')[1])/60,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let week=monday(today),undo=null,result;const demoWeek=monday(addDays(today,new Date().getDay()===0?1:0));week=demoWeek;
const initial={version:1,sleep:{bed:'23:00',hours:8},tasks:[{id:'math',title:'Examen de matemáticas',due:addDays(demoWeek,4),hours:6},{id:'design',title:'Entrega de proyecto',due:addDays(demoWeek,7),hours:5}],fixed:[{id:'class',title:'Clases',days:[1,2,3,4,5],start:9,end:14},{id:'sport',title:'Entrenamiento',days:[2,4],start:18,end:19}],social:[{id:'friends',title:'Café con amigos',date:addDays(demoWeek,5),start:17,end:18}]};
