function valid(s){return s&&s.version===1&&s.sleep&&/^\d\d:\d\d$/.test(s.sleep.bed)&&num(s.sleep.bed)<24&&s.sleep.hours>=4&&s.sleep.hours<=12&&['tasks','fixed','social'].every(k=>Array.isArray(s[k]))&&s.tasks.every(t=>typeof t.title==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(t.due)&&t.hours>0&&t.hours<=300)&&[...s.fixed,...s.social].every(e=>typeof e.title==='string'&&e.start>=0&&e.end<=24&&e.end>e.start)&&s.fixed.every(e=>Array.isArray(e.days)&&e.days.every(d=>d>=0&&d<=6))&&s.social.every(e=>/^\d{4}-\d{2}-\d{2}$/.test(e.date))}
