function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4000)}
function render(){result=Planner.plan(state,week);$('todayLabel').textContent=new Date().toLocaleDateString('es-ES',{weekday:'long',day:'numeric',month:'long'});$('focus').textContent=result.studyHours+' h esta semana';$('sleepStat').textContent=state.sleep.hours+' h cada noche';$('bedStat').textContent='A dormir a las '+state.sleep.bed;$('socialStat').textContent=state.social.filter(e=>e.date>=week&&e.date<addDays(week,7)).length+' planes personales';$('range').textContent=new Date(week+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'long'})+' — '+new Date(addDays(week,6)+'T12:00:00').toLocaleDateString('es-ES',{day:'numeric',month:'long',year:'numeric'});$('sleepFooter').textContent=state.sleep.bed+' — '+fmt((num(state.sleep.bed)+state.sleep.hours)%24);
let html='<div></div>';for(let i=0;i<7;i++){let d=addDays(week,i);html+=`<div class="dayhead ${d===today?'today':''}">${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'][i]}<strong>${Number(d.slice(-2))}</strong></div>`}html+='<div class="timecol">';for(let h=8;h<=22;h+=2)html+=`<span class="time" style="top:${(h-8)/14*100}%">${fmt(h)}</span>`;html+='</div>';for(let i=0;i<7;i++){let d=addDays(week,i);html+='<div class="daycol">';for(const e of result.events.filter(e=>e.date===d&&e.end>8&&e.start<22)){let start=Math.max(8,e.start),end=Math.min(22,e.end);html+=`<div class="event ${e.type}" style="top:${(start-8)/14*100}%;height:${(end-start)/14*100}%" title="${esc(e.title)} · ${fmt(e.start)}–${fmt(e.end)}"><b>${esc(e.title)}</b><small>${fmt(e.start)}–${fmt(e.end)}</small></div>`}html+='</div>'}$('calendar').innerHTML=html;
$('upcoming').innerHTML=[...state.tasks].sort((a,b)=>a.due.localeCompare(b.due)).slice(0,3).map(t=>`<div class="deadline"><div class="datebox">${new Date(t.due+'T12:00:00').toLocaleDateString('es',{month:'short'})}<strong>${Number(t.due.slice(-2))}</strong></div><div><p>${esc(t.title)}</p><small>${t.due<today?'Revisa esta fecha; ya ha pasado':t.due===today?'Es hoy. Respira y revisa tu preparación.':`Quedan ${Math.round((new Date(t.due+'T12:00:00')-new Date(today+'T12:00:00'))/86400000)} días · ${t.hours} h de preparación`}</small></div></div>`).join('')||'<p>Aquí aparecerán tus próximos objetivos.</p>';
$('warning').textContent=result.pending.length?'Hay horas que no caben en esta semana antes de su fecha: '+result.pending.map(p=>p.title+' ('+p.hours+' h)').join(', ')+'. Amplía la disponibilidad o revisa los objetivos. No se han dado por completadas.':'';
$('items').innerHTML=['tasks','fixed','social'].flatMap(k=>state[k].map(e=>`<div class="item"><div>${esc(e.title)}<small>${k==='tasks'?e.due+' · '+e.hours+' h pendientes':k==='fixed'?'Rutina semanal · '+fmt(e.start)+'–'+fmt(e.end):e.date+' · '+fmt(e.start)+'–'+fmt(e.end)}</small></div><button data-kind="${k}" data-id="${esc(e.id)}" aria-label="Eliminar ${esc(e.title)}">×</button></div>`)).join('');}
function checkpoint(){undo=structuredClone(state)}
function sleepConflict(start,end){let bed=num(state.sleep.bed),wake=(bed+state.sleep.hours)%24;return bed>wake?(end>bed||start<wake):(start<wake&&end>bed)}
function eventError(e,kind){if(e.end<=e.start)return 'La hora final debe ser posterior a la inicial. Divide los eventos que crucen medianoche.';if(sleepConflict(e.start,e.end))return 'Ese horario coincide con tu descanso. Ajusta el horario o tu preferencia de sueño.';const days=kind==='fixed'?Array.from({length:7},(_,i)=>addDays(week,i)).filter(d=>e.days.includes(new Date(d+'T12:00:00').getDay())):[e.date];for(const date of days){let dow=new Date(date+'T12:00:00').getDay();if([...state.fixed.filter(x=>x.days.includes(dow)),...state.social.filter(x=>x.date===date)].some(x=>e.start<x.end&&e.end>x.start))return 'Coincide con una rutina o un plan personal. Revisa ese compromiso primero.'}return ''}
