$('add').onclick=()=>{$('formError').textContent='';$('due').value=addDays(today,7);$('eventDate').value=today;$('modal').showModal()};$('close').onclick=()=>$('modal').close();$('kind').onchange=()=>{let k=$('kind').value;$('taskFields').hidden=k!=='task';$('eventFields').hidden=k==='task';$('daysLabel').hidden=k!=='fixed';$('dateLabel').hidden=k==='fixed';$('due').required=k==='task';$('eventDate').required=k==='social'};
$('entry').onsubmit=e=>{e.preventDefault();let kind=$('kind').value,title=$('title').value.trim();if(!title)return;let error='';if(kind==='task'){if(!$('due').value||!$('hours').value)return;checkpoint();state.tasks.push({id:crypto.randomUUID(),title,due:$('due').value,hours:Number($('hours').value)});save()}else{let event={id:crypto.randomUUID(),title,start:num($('from').value),end:num($('to').value)};if(kind==='fixed'){event.days=[...$('days').selectedOptions].map(o=>+o.value);if(!event.days.length)error='Sélectiona al menos un día.'}else event.date=$('eventDate').value;if(!error)error=addEvent(event,kind==='fixed'?'fixed':'social')}if(error){$('formError').textContent=error;return}$('modal').close();$('title').value='';toast('Tu semana está actualizada')};
$('prev').onclick=()=>{week=addDays(week,-7);render()};$('next').onclick=()=>{week=addDays(week,7);render()};$('now').onclick=()=>{week=monday(today);render()};$('weekNav').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('goalsNav').onclick=()=>$('details').scrollIntoView({behavior:'smooth'});
$('rhythmNav').onclick=()=>{$('bed').value=state.sleep.bed;$('sleepHours').value=state.sleep.hours;$('sleepModal').showModal()};$('closeSleep').onclick=()=>$('sleepModal').close();
function changeSleep(bed,hours){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(bed)||hours<4||hours>12)return 'Revisa la hora y las horas de sueño.';let next=structuredClone(state);next.sleep={bed,hours};let old=state;state=next;let conflict=[...state.fixed,...state.social].some(e=>sleepConflict(e.start,e.end));state=old;if(conflict)return 'Ese descanso coincide con un compromiso fijo. Ajusta primero ese compromiso.';let before=Planner.plan(state,week),after=Planner.plan(next,week);if(after.studyHours<before.studyHours)return 'Ese descanso deja horas de estudio sin hueco. Revisa la disponibilidad antes de aplicarlo.';checkpoint();state=next;save();return ''}
$('sleepForm').onsubmit=e=>{e.preventDefault();let err=changeSleep($('bed').value,+$('sleepHours').value);if(err){toast(err);return}$('sleepModal').close();toast('Descanso actualizado')};
$('items').onclick=e=>{const b=e.target.closest('button');if(!b)return;checkpoint();state[b.dataset.kind]=state[b.dataset.kind].filter(x=>x.id!==b.dataset.id);save();toast('Eliminado. Escribe «deshacer» para recuperarlo.')};
$('example').onclick=()=>{$('prompt').value='Cena con amigos el viernes de 20:00 a 22:00';$('prompt').focus()};$('sleepExample').onclick=()=>{$('prompt').value='Quiero dormir 8 horas';$('prompt').focus()};
$('chat').onsubmit=e=>{e.preventDefault();let raw=$('prompt').value,text=raw.toLowerCase(),reply;if(text.includes('deshacer')){if(undo){let prev=undo;undo=structuredClone(state);state=prev;save();reply='Cambio deshecho. Tu plan anterior está recuperado.'}else reply='Todavía no hay cambios que deshacer en esta sesión.'}else if(text.includes('dormir')){let hours=text.match(/(\d+(?:[.,]\d+)?)\s*horas/),bed=text.match(/(?:a las|acostarme a las)\s*(\d{1,2}:\d{2})/);if(hours&&+hours[1].replace(',','.')>=4&&+hours[1].replace(',','.')<=12){let err=changeSleep(bed?bed[1]:state.sleep.bed,+hours[1].replace(',','.'));reply=err||'He protegido tu descanso y reorganizado el estudio. Puedes escribir «deshacer».'}else reply='Indica las horas: «Quiero dormir 8 horas». Puedes ajustar la hora en Mi ritmo.'}else{let times=[...text.matchAll(/\b(\d{1,2}):([0-5]\d)\b/g)].map(m=>+m[1]+ +m[2]/60),date=text.match(/\b\d{4}-\d{2}-\d{2}\b/),names=['lunes','martes','miércoles','jueves','viernes','sábado','domingo'],di=names.findIndex(n=>text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(n.normalize('NFD').replace(/[\u0300-\u036f]/g,'')));if(times.length===2&&times.every(h=>h<24)&&(date||di>=0)){let day=date?date[0]:addDays(week,di),title=raw.split(/\s+(?:el|de|desde)\s/i)[0].trim()||'Plan personal';let err=addEvent({id:crypto.randomUUID(),title,date:day,start:times[0],end:times[1]},'social');reply=err||`He añadido «${title}» el ${day}. Se mantienen ${result.studyHours} h de estudio esta semana y tu descanso. Escribe «deshacer» para volver al plan anterior.`}else reply='Puedo añadir planes con «Cena el viernes de 20:00 a 22:00» o «Cena el 2026-12-04 de 20:00 a 22:00», ajustar «Quiero dormir 8 horas» y «deshacer». Para exámenes y rutinas usa Añadir al plan.'}$('reply').textContent=reply;$('prompt').value=''};
