$('backup').onclick=()=>download(JSON.stringify(state,null,2),'application/json','brisa-datos.json');$('restore').onchange=async e=>{try{let s=JSON.parse(await e.target.files[0].text());if(!valid(s))throw Error();checkpoint();state=s;save();toast('Copia restaurada')}catch{toast('No se pudo leer esa copia de Brisa')}e.target.value=''};
$('export').onclick=()=>{let stamp=(date,h)=>{if(h===24)return addDays(date,1).replaceAll('-','')+'T000000';return date.replaceAll('-','')+'T'+fmt(h).replace(':','')+'00'},escapeICS=s=>s.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Brisa//Plan//ES'];result.events.forEach((e,i)=>lines.push('BEGIN:VEVENT','UID:'+e.id+'-'+e.date+'-'+i+'@brisa','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z'),'DTSTART:'+stamp(e.date,e.start),'DTEND:'+stamp(e.date,e.end),'SUMMARY:'+escapeICS(e.title),'BEGIN:VALARM','TRIGGER:-PT30M','ACTION:DISPLAY','DESCRIPTION:Tu siguiente paso está cerca. Tómate un momento para prepararte.','END:VALARM','END:VEVENT'));lines.push('END:VCALENDAR');download(lines.join('\r\n'),'text/calendar','brisa-semana.ics')};render();
